create table public.class_teachers (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.classrooms (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null check (char_length(btrim(title)) between 1 and 120), description text not null default '' check (char_length(description) <= 1000), access_code text not null unique default upper(encode(extensions.gen_random_bytes(12), 'hex')), created_at timestamptz not null default now());
create table public.class_members (class_id uuid not null references public.classrooms(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, joined_at timestamptz not null default now(), primary key (class_id, user_id));
create table public.class_assignments (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classrooms(id) on delete cascade, title text not null check (char_length(btrim(title)) between 1 and 200), instructions text not null check (char_length(btrim(instructions)) between 1 and 5000), resource_url text check (resource_url is null or (char_length(resource_url) <= 2048 and resource_url ~* '^https?://[^[:space:]]+$')), created_at timestamptz not null default now());
create table public.class_submissions (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.class_assignments(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, content text not null check (char_length(btrim(content)) between 1 and 10000), link_url text check (link_url is null or (char_length(link_url) <= 2048 and link_url ~* '^https?://[^[:space:]]+$')), submitted_at timestamptz not null default now(), unique (assignment_id, user_id));
create table public.class_join_attempts (user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create index class_join_attempts_user_time_idx on public.class_join_attempts(user_id, created_at desc);
create index class_members_user_idx on public.class_members(user_id, class_id);
create index class_assignments_class_idx on public.class_assignments(class_id, created_at desc);
create index class_submissions_assignment_idx on public.class_submissions(assignment_id);
alter table public.class_teachers enable row level security;
alter table public.classrooms enable row level security;
alter table public.class_members enable row level security;
alter table public.class_assignments enable row level security;
alter table public.class_submissions enable row level security;
alter table public.class_join_attempts enable row level security;
revoke all on public.class_teachers, public.classrooms, public.class_members, public.class_assignments, public.class_submissions, public.class_join_attempts from public, anon, authenticated;
grant select on public.class_teachers to authenticated;
grant select (id, owner_id, title, description, created_at) on public.classrooms to authenticated;
grant select on public.class_members to authenticated;
grant select, insert on public.class_assignments to authenticated;
grant select, insert on public.class_submissions to authenticated;
create policy class_teachers_own on public.class_teachers for select to authenticated using (user_id = (select auth.uid()));
create function public.is_class_teacher(p_class_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.classrooms c join public.class_teachers t on t.user_id = c.owner_id where c.id = p_class_id and c.owner_id = (select auth.uid())); $$;
create function public.is_class_member(p_class_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select public.is_class_teacher(p_class_id) or exists (select 1 from public.class_members m where m.class_id = p_class_id and m.user_id = (select auth.uid())); $$;
revoke all on function public.is_class_teacher(uuid), public.is_class_member(uuid) from public, anon;
grant execute on function public.is_class_teacher(uuid), public.is_class_member(uuid) to authenticated;
create policy classrooms_member_read on public.classrooms for select to authenticated using (public.is_class_member(id));
create policy class_members_read on public.class_members for select to authenticated using (user_id = (select auth.uid()) or public.is_class_teacher(class_id));
create policy class_assignments_read on public.class_assignments for select to authenticated using (public.is_class_member(class_id));
create policy class_assignments_teacher_insert on public.class_assignments for insert to authenticated with check (public.is_class_teacher(class_id));
create policy class_submissions_read on public.class_submissions for select to authenticated using ((user_id = (select auth.uid()) and exists (select 1 from public.class_assignments a where a.id=assignment_id and public.is_class_member(a.class_id))) or exists (select 1 from public.class_assignments a where a.id=assignment_id and public.is_class_teacher(a.class_id)));
create policy class_submissions_insert on public.class_submissions for insert to authenticated with check (user_id = (select auth.uid()) and exists (select 1 from public.class_assignments a join public.class_members m on m.class_id=a.class_id where a.id=assignment_id and m.user_id=(select auth.uid())));
grant update (content, link_url) on public.class_submissions to authenticated;
create policy class_submissions_update on public.class_submissions for update to authenticated using (user_id = (select auth.uid()) and exists (select 1 from public.class_assignments a join public.class_members m on m.class_id=a.class_id where a.id=assignment_id and m.user_id=(select auth.uid()))) with check (user_id = (select auth.uid()) and exists (select 1 from public.class_assignments a join public.class_members m on m.class_id=a.class_id where a.id=assignment_id and m.user_id=(select auth.uid())));
create function public.create_classroom(p_title text, p_description text default '') returns uuid language plpgsql security definer set search_path = '' as $$ declare v_id uuid; v_uid uuid := auth.uid(); begin if v_uid is null or not exists (select 1 from public.class_teachers where user_id=v_uid) then raise exception 'Apenas professores autorizados podem criar turmas' using errcode='42501'; end if; insert into public.classrooms(owner_id,title,description) values(v_uid,btrim(p_title),coalesce(btrim(p_description),'')) returning id into v_id; return v_id; end; $$;
create function public.classroom_code(p_class_id uuid) returns text language plpgsql stable security definer set search_path = '' as $$ declare v_code text; begin if not public.is_class_teacher(p_class_id) then raise exception 'Sem acesso ao código' using errcode='42501'; end if; select access_code into v_code from public.classrooms where id=p_class_id; return v_code; end; $$;
create function public.join_classroom(p_code text) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_uid uuid := auth.uid(); v_id uuid; v_code text := upper(btrim(coalesce(p_code,''))); begin if v_uid is null then raise exception 'Autenticação necessária' using errcode='42501'; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('class_join:' || v_uid::text, 0)); delete from public.class_join_attempts where user_id=v_uid and created_at < now()-interval '1 day'; if (select count(*) from public.class_join_attempts where user_id=v_uid and created_at > now()-interval '1 minute') >= 10 then return jsonb_build_object('ok',false,'reason','rate'); end if; insert into public.class_join_attempts(user_id) values (v_uid); if v_code ~ '^[A-F0-9]{24}$' then select id into v_id from public.classrooms where access_code=v_code; end if; if v_id is null then return jsonb_build_object('ok',false,'reason','invalid'); end if; if exists (select 1 from public.classrooms where id=v_id and owner_id=v_uid) then return jsonb_build_object('ok',true,'class_id',v_id); end if; insert into public.class_members(class_id,user_id) values(v_id,v_uid) on conflict do nothing; return jsonb_build_object('ok',true,'class_id',v_id); end; $$;
create function public.set_class_teacher(p_email text, p_enabled boolean) returns void language plpgsql security definer set search_path = '' as $$ declare v_id uuid; begin if not public.is_admin() then raise exception 'Acesso reservado' using errcode='42501'; end if; if p_enabled is null then raise exception 'Estado inválido'; end if; select id into v_id from auth.users where lower(email)=lower(btrim(p_email)) limit 1; if v_id is null then raise exception 'Conta não encontrada'; end if; if p_enabled then insert into public.class_teachers(user_id) values(v_id) on conflict do nothing; else delete from public.class_teachers where user_id=v_id; end if; end; $$;
create function public.list_class_teachers() returns table(user_id uuid, email text) language plpgsql stable security definer set search_path = '' as $$ begin if not public.is_admin() then raise exception 'Acesso reservado' using errcode='42501'; end if; return query select t.user_id, u.email::text from public.class_teachers t join auth.users u on u.id=t.user_id order by u.email; end; $$;
create function public.class_assignment_submissions(p_assignment_id uuid) returns table(id uuid, student_name text, content text, link_url text, submitted_at timestamptz) language plpgsql stable security definer set search_path = '' as $$ begin if not exists (select 1 from public.class_assignments a where a.id=p_assignment_id and public.is_class_teacher(a.class_id)) then raise exception 'Acesso reservado' using errcode='42501'; end if; return query select s.id, coalesce(nullif(btrim(p.display_name),''),'Estudante'), s.content, s.link_url, s.submitted_at from public.class_submissions s left join public.profiles p on p.id=s.user_id where s.assignment_id=p_assignment_id order by s.submitted_at desc; end; $$;
revoke all on function public.create_classroom(text,text), public.classroom_code(uuid), public.join_classroom(text), public.set_class_teacher(text,boolean), public.list_class_teachers(), public.class_assignment_submissions(uuid) from public, anon;
grant execute on function public.create_classroom(text,text), public.classroom_code(uuid), public.join_classroom(text), public.set_class_teacher(text,boolean), public.list_class_teachers(), public.class_assignment_submissions(uuid) to authenticated;
